// Las fechas grabadas (DD.MM.AAAA) tienen la mayor tasa de error (8.6 %).
const p = $json.body ?? $json;
const t = String(p.texto_grabado ?? '').trim();
const problemas = [];
if (!t) problemas.push('texto vacío');
if (t.length > 20) problemas.push(`texto de ${t.length} caracteres (máx. 20)`);
if (/[^A-Za-zÁÉÍÓÚáéíóúÑñÜü0-9 .&'\-]/.test(t)) problemas.push('caracteres no grabables');
const f = t.match(/^(\d{2})\.(\d{2})\.(\d{4})$/);
if (f) {
  const d = new Date(+f[3], +f[2]-1, +f[1]);
  if (d.getDate() !== +f[1] || d.getMonth() !== +f[2]-1) problemas.push('fecha inexistente');
}
// Promesa realista = producción estándar del producto + envío (en lugar de 7 días fijos)
const PROD = { default: 6 }, ENVIO = 3;
const dias = (PROD[p.id_producto] ?? PROD.default) + ENVIO;
const prom = new Date(Date.now() + dias * 86400000).toISOString().slice(0,10);
const especial = p.fecha_especial ? new Date(p.fecha_especial) : null;
const alerta_especial = especial && new Date(prom) > especial;
return [{ json: { ...p, texto_grabado: t, problemas, ok: problemas.length === 0,
                  fecha_prometida: prom, alerta_especial } }];
